import{_ as e,o as t,c as s,a2 as l}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"L1 指南：从零写一个模块","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/writing-modules.md","filePath":"zh/l1/writing-modules.md"}'),n={name:"zh/l1/writing-modules.md"};function o(d,a,i,r,c,p){return t(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="l1-指南-从零写一个模块" tabindex="-1">L1 指南：从零写一个模块 <a class="header-anchor" href="#l1-指南-从零写一个模块" aria-label="Permalink to &quot;L1 指南：从零写一个模块&quot;">​</a></h1><p>完整流程：源码 → 接口调用 → 加载 → 运行。</p><h2 id="步骤-1-选择你的加载路径" tabindex="-1">步骤 1 - 选择你的加载路径 <a class="header-anchor" href="#步骤-1-选择你的加载路径" aria-label="Permalink to &quot;步骤 1 - 选择你的加载路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>何时</th><th>如何</th></tr></thead><tbody><tr><td>编译进内核</td><td>你的模块随内核构建一同发布</td><td>编译进内核，从 kmain 或内置 Shell 调用你的初始化函数</td></tr><tr><td>共享对象</td><td>无需重建内核即可部署</td><td>构建 .so 文件，通过 ld.so 接口面加载</td></tr><tr><td>嵌入式工具</td><td>发送 ELF 载荷</td><td><code>tool_register(name, elf, size)</code> 然后 <code>run name</code></td></tr></tbody></table><h2 id="步骤-2-你所构建的接口面" tabindex="-1">步骤 2 - 你所构建的接口面 <a class="header-anchor" href="#步骤-2-你所构建的接口面" aria-label="Permalink to &quot;步骤 2 - 你所构建的接口面&quot;">​</a></h2><p>对于一个带有 Shell 命令和部分功能的模块：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;l1_ext.h&quot;          /* shell bridge, config, ... */</span></span>
<span class="line"><span>#include &quot;l1_wp8cd.h&quot;        /* shell_register_builtin, jobs */</span></span>
<span class="line"><span></span></span>
<span class="line"><span>static int cmd_mymod(const char *args) {</span></span>
<span class="line"><span>    /* parse args, do the work, print through the console hook */</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>void mymod_init(void) {</span></span>
<span class="line"><span>    l1_ext_shell_register_command_ex(</span></span>
<span class="line"><span>        &quot;mymod&quot;, cmd_mymod, &quot;my module - does the thing&quot;, &quot;L1-demo&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>对于 UI：添加 <code>tui_menu_register</code> / <code>tui_page_register</code>。对于存储： <code>driver_block_register</code>。参见各接口面页面。</p><h2 id="步骤-3-构建" tabindex="-1">步骤 3 - 构建 <a class="header-anchor" href="#步骤-3-构建" aria-label="Permalink to &quot;步骤 3 - 构建&quot;">​</a></h2><ul><li>编译进内核：你的 .c 文件放入对应的目录树；Makefile 通过通配符自动拾取；从 <code>mymod_init</code> 注册。</li><li>共享对象：针对接口面头文件构建 ELF .so，然后在客户机内（或从你的加载器中）执行 <code>so_load(name, flags)</code> + <code>symbol_resolve</code>/<code>dlsym_impl</code> 获取初始化符号 - 完整机制参见 <a href="./solib-loader.html">solib-loader.md</a>。</li></ul><h2 id="步骤-4-测试" tabindex="-1">步骤 4 - 测试 <a class="header-anchor" href="#步骤-4-测试" aria-label="Permalink to &quot;步骤 4 - 测试&quot;">​</a></h2><ul><li><code>run &lt;yourprog&gt;</code> / 调用你的命令；检查 <code>help -w</code> 是否显示你的标签。</li><li>完整的检查条目来自 <a href="./../root/CONTRIBUTING.html">CONTRIBUTING.md</a>：构建保持 0 警告，回归测试仍通过 28/28， 命令计数基线正好增加你的命令数。</li><li><code>l1test</code> 和 <code>l1_ext_self_test()</code> 测试接口面本身。</li></ul><h2 id="规则须知" tabindex="-1">规则须知 <a class="header-anchor" href="#规则须知" aria-label="Permalink to &quot;规则须知&quot;">​</a></h2><ul><li>系统输出的所有内容仅使用 ASCII 字符串。</li><li>有界表格需命名限制常量 + 明确拒绝越界。</li><li>文档：你的命令页面通过 <code>make api-docs</code> 自动生成；你所属领域的手册章节是 PR 的一部分。</li></ul>`,14)])])}const m=e(n,[["render",o]]);export{u as __pageData,m as default};
